/**
 * Auth user resolve — group unique ids → GET /users/{id} (Auth via BFF).
 * Dùng cho list display Người tạo / id liên quan (không lặp N+1 cùng 1 user).
 */
import { apiClient, unwrap, type BffResponse } from '../api';

export type AuthUserBrief = {
  id: string;
  fullName: string;
  username: string;
  staffId?: string;
  email?: string;
};

type BffUserDto = {
  id?: string;
  fullName?: string;
  firstName?: string;
  lastName?: string;
  username?: string;
  staffId?: string;
  email?: string;
};

const cache = new Map<string, AuthUserBrief | null>();

const UUID_RE =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

export function looksLikeAuthUserId(value: string | null | undefined): boolean {
  return UUID_RE.test((value || '').trim());
}

function mapBffUser(dto: BffUserDto, fallbackId: string): AuthUserBrief {
  const fullName =
    (dto.fullName || '').trim()
    || [dto.firstName, dto.lastName].filter(Boolean).join(' ').trim()
    || (dto.username || '').trim()
    || fallbackId;
  return {
    id: (dto.id || fallbackId).trim() || fallbackId,
    fullName,
    username: (dto.username || '').trim(),
    staffId: dto.staffId?.trim() || undefined,
    email: dto.email?.trim() || undefined,
  };
}

export function formatAuthUserDisplay(
  user: AuthUserBrief | null | undefined,
  fallbackId?: string | null,
): string {
  if (!user) return (fallbackId || '').trim() || '—';
  const name = (user.fullName || '').trim();
  const code = (user.staffId || user.username || '').trim();
  if (name && code && !name.includes(code)) return `${code} — ${name}`;
  return name || code || (fallbackId || '').trim() || '—';
}

async function fetchUserById(id: string): Promise<AuthUserBrief | null> {
  const key = id.trim();
  if (!key) return null;
  if (cache.has(key)) return cache.get(key) ?? null;
  try {
    const res = await apiClient.get<BffResponse<BffUserDto>>(`/users/${encodeURIComponent(key)}`);
    const dto = unwrap(res);
    const mapped = mapBffUser(dto ?? {}, key);
    cache.set(key, mapped);
    return mapped;
  } catch {
    cache.set(key, null);
    return null;
  }
}

/** GET /users/me — default Người import lúc tạo IMP. */
export async function getCurrentAuthUser(): Promise<AuthUserBrief | null> {
  try {
    const res = await apiClient.get<BffResponse<BffUserDto>>('/users/me');
    const dto = unwrap(res);
    const id = (dto?.id || '').trim();
    if (!id) return null;
    const mapped = mapBffUser(dto ?? {}, id);
    cache.set(id, mapped);
    return mapped;
  } catch {
    return null;
  }
}

/**
 * Group unique ids → parallel Auth GET (cached).
 * Trả Map id → user (thiếu id thì không có entry).
 */
export async function resolveAuthUsersByIds(
  ids: Array<string | null | undefined>,
): Promise<Map<string, AuthUserBrief>> {
  const unique = [
    ...new Set(
      ids
        .map(x => (x || '').trim())
        .filter(x => x.length > 0),
    ),
  ];
  const result = new Map<string, AuthUserBrief>();
  if (unique.length === 0) return result;

  await Promise.all(
    unique.map(async id => {
      const user = await fetchUserById(id);
      if (user) result.set(id, user);
    }),
  );
  return result;
}
