/** Mức XL IMP — filter + badge (GAP-IMP-VOUCHER-11). */
export const IMPORT_SAO_KE_PROCESSING_OPTIONS = [
  { value: '', label: 'Tất cả mức' },
  { value: '1', label: '1 — Draft' },
  { value: '3', label: '3 — Lập chứng từ' },
  { value: '5', label: '5 — Đã xác nhận' },
] as const;

export function formatImportSaoKeProcessingLevel(level: string | undefined): string {
  const lv = (level || '').trim();
  const hit = IMPORT_SAO_KE_PROCESSING_OPTIONS.find(o => o.value === lv);
  return hit?.label ?? (lv || '—');
}

/** Resume wizard step từ mức XL: 1→phân loại · 3/5→dry-run/confirm. */
export function resolveImportResumeStep(processingLevel: string | undefined): 3 | 4 {
  const lv = (processingLevel || '1').trim();
  if (lv === '3' || lv === '5') return 4;
  return 3;
}

export type ImportSaoKeSide = 'thu' | 'chi' | 'thu/chi';

export function parseImportSaoKeMonth(
  monthCode: string | undefined,
): { year: number; month: number } | null {
  const raw = (monthCode || '').trim();
  const m = raw.match(/^(\d{4})-?(\d{2})(?:-\d{2})?$/);
  if (!m) return null;
  const year = Number(m[1]);
  const month = Number(m[2]);
  if (!Number.isFinite(year) || month < 1 || month > 12) return null;
  return { year, month };
}

export function resolveImportSaoKeSide(input: {
  importedByName?: string;
  totalCredit?: number;
  totalDebit?: number;
}): ImportSaoKeSide {
  const name = (input.importedByName || '').toLowerCase();
  const hasChi = /(^|[\s_\-])chi($|[\s_\-])/.test(name);
  const hasThu = /(^|[\s_\-])thu($|[\s_\-])/.test(name);
  if (hasChi && !hasThu) return 'chi';
  if (hasThu && !hasChi) return 'thu';
  const debit = input.totalDebit ?? 0;
  const credit = input.totalCredit ?? 0;
  if (debit > 0 && credit === 0) return 'chi';
  if (credit > 0 && debit === 0) return 'thu';
  return 'thu/chi';
}

/** «Import sao kê chi 12-2026» — chỉ hiện Title đã lưu (UI detect / seed). */
export function formatImportSaoKeTitle(input: {
  monthCode?: string;
  importedByName?: string;
  totalCredit?: number;
  totalDebit?: number;
  title?: string;
}): string {
  return (input.title || '').trim();
}

function parseTxnDateParts(raw: string | undefined): { year: number; month: number } | null {
  const s = (raw || '').trim();
  if (s.length < 6) return null;
  const iso = s.match(/^(\d{4})[-/.](\d{1,2})(?:[-/.]\d{1,2})?/);
  if (iso) {
    const year = Number(iso[1]);
    const month = Number(iso[2]);
    if (year >= 2000 && month >= 1 && month <= 12) return { year, month };
  }
  const dmy = s.match(/^(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})/);
  if (dmy) {
    const year = Number(dmy[3]);
    const month = Number(dmy[2]);
    if (year >= 2000 && month >= 1 && month <= 12) return { year, month };
  }
  const compact = s.match(/^(\d{4})(\d{2})\d{2}$/);
  if (compact) {
    const year = Number(compact[1]);
    const month = Number(compact[2]);
    if (year >= 2000 && month >= 1 && month <= 12) return { year, month };
  }
  return null;
}

/** Title + kỳ từ ngày GD / thu-chi trên file user import (không dùng cho seed). */
export function detectImportSaoKeTitleFromRows(rows: Array<{
  transactionDate?: string;
  creditAmount?: number;
  debitAmount?: number;
  amount?: number;
}>): { title: string; monthCode: string } | null {
  const counts = new Map<string, { year: number; month: number; n: number }>();
  let credit = 0;
  let debit = 0;
  for (const r of rows) {
    credit += r.creditAmount ?? 0;
    debit += r.debitAmount ?? (r.creditAmount ? 0 : r.amount ?? 0);
    const p = parseTxnDateParts(r.transactionDate);
    if (!p) continue;
    const key = `${p.year}-${p.month}`;
    const prev = counts.get(key);
    counts.set(key, { year: p.year, month: p.month, n: (prev?.n ?? 0) + 1 });
  }
  if (counts.size === 0) return null;
  const best = [...counts.values()].sort((a, b) => b.n - a.n || b.year - a.year || b.month - a.month)[0];
  const side = resolveImportSaoKeSide({ totalCredit: credit, totalDebit: debit });
  return {
    title: `Import sao kê ${side} ${String(best.month).padStart(2, '0')}-${best.year}`,
    monthCode: `${best.year}-${String(best.month).padStart(2, '0')}`,
  };
}

