import React, { useCallback, useMemo, useState } from 'react';
import {
  Button,
  Modal,
  Select,
  SearchTextInput,
  detectDateRangePreset,
  dispatchAppToast,
  ErpDataListGrid,
  LIN_ERP_LIST_FILTER_LAYOUT,
  LinErpListFilterBar,
  LinPageLayout,
  buildVoucherListToolbarActions,
  useViewMobileLayout,
} from '@linm-soft-org/linm-web-common-components';
import { useInAppNavigate } from '../../../router/useInAppNavigate';
import { useAppDispatch } from '../../../store/hooks';
import { useVoucherListFilterState } from '../../../hooks/useVoucherListFilterState';
import { useVoucherListSelection } from '../../../hooks/useVoucherListSelection';
import { useImportSaoKePermissions } from '../../../hooks/useImportSaoKePermissions';
import { bankStatementImportService } from '../../../services/kt/bankStatementImportService';
import type { BankStatementImportVoucherListItem } from '../../../services/kt/bankStatementImportModels';
import {
  formatAuthUserDisplay,
  looksLikeAuthUserId,
  resolveAuthUsersByIds,
  type AuthUserBrief,
} from '../../../services/auth/authUsers';
import { getApiErrorMessage } from '../../../utils/getApiErrorMessage';
import { formatDateLocal, formatMoney } from '../../../utils/formatters';
import {
  VOUCHER_LIST_ROW_MENU_HINT_DESKTOP,
  VOUCHER_LIST_ROW_MENU_HINT_TOUCH,
  voucherListRowMenuHintDismissStorageKey,
} from '../../../utils/voucherListRowMenuHint';
import { LIST_FILTER_SCOPE } from '../../../constants/listFilterScopes';
import {
  IMPORT_SAO_KE_LIST_LABELS,
  IMPORT_SAO_KE_PROCESSING_OPTIONS,
  formatImportSaoKeProcessingLevel,
  formatImportSaoKeTitle,
  resolveImportResumeStep,
} from '../../../constants/importSaoKeLabels';
import { KT } from '../../../router/paths';
import erp from '../../../styles/erpPage.module.css';
import styles from './ImportSaoKeListPage.module.css';
import {
  DEFAULT_PAGE_SIZE,
  VoucherListPagination,
  type ListPageSize,
} from '../../../components/list/VoucherListPagination';
import { useVoucherListTableBusy } from '../../../components/list/useVoucherListTableBusy';
import { VoucherRowActionMenu, type VoucherRowMenuAction } from '../../../components/voucher-list';

const PAGE_SIZE = DEFAULT_PAGE_SIZE;
const testIdPrefix = 'kt-import-sao-ke';
const pageId = testIdPrefix;
const labels = IMPORT_SAO_KE_LIST_LABELS;

type ListRow = BankStatementImportVoucherListItem & {
  createdByDisplay?: string;
  importedByDisplay?: string;
};

function canDeleteImp(row: BankStatementImportVoucherListItem | null | undefined): boolean {
  if (!row) return false;
  return (row.processingLevel || '').trim() !== '5';
}

/** Ưu tiên tên đã lưu; nếu code là Auth userId thì resolve tên từ Auth map. */
function displayImportedBy(
  row: BankStatementImportVoucherListItem,
  authById: Map<string, AuthUserBrief>,
): string {
  const name = (row.importedByName || '').trim();
  const code = (row.importedByEmployeeCode || '').trim();
  if (name) {
    if (code && !name.includes(code)) return `${code} — ${name}`;
    return name;
  }
  if (looksLikeAuthUserId(code)) {
    return formatAuthUserDisplay(authById.get(code), code);
  }
  if (code) {
    for (const u of authById.values()) {
      if ((u.staffId || '').localeCompare(code, undefined, { sensitivity: 'accent' }) === 0) {
        return formatAuthUserDisplay(u, code);
      }
    }
    return code;
  }
  return '—';
}

function displayCreatedBy(
  row: BankStatementImportVoucherListItem,
  authById: Map<string, AuthUserBrief>,
): string {
  const id = (row.createdBy || '').trim();
  if (!id) return '—';
  return formatAuthUserDisplay(authById.get(id), id);
}


const ImportSaoKeListPage: React.FC = () => {
  const dispatch = useAppDispatch();
  const navigate = useInAppNavigate();
  const viewMobile = useViewMobileLayout();
  const { canCreate, canUpdate, canDelete } = useImportSaoKePermissions();

  const {
    initialized,
    fromDate,
    toDate,
    applyDateRange,
    processingLevel,
    setProcessingLevel,
    page,
    setPage,
    resetPage,
  } = useVoucherListFilterState(LIST_FILTER_SCOPE.importSaoKe);

  const [searchDraft, setSearchDraft] = useState('');
  const [search, setSearch] = useState('');
  const [companyCodeDraft, setCompanyCodeDraft] = useState('');
  const [companyCode, setCompanyCode] = useState('');
  const [items, setItems] = useState<ListRow[]>([]);
  const [totalCount, setTotalCount] = useState(0);
  const [loading, setLoading] = useState(false);
  const [reloadKey, setReloadKey] = useState(0);
  const [pageSize, setPageSizeState] = useState<ListPageSize>(PAGE_SIZE);
  const [rowMenu, setRowMenu] = useState<{ x: number; y: number; row: ListRow } | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<ListRow | null>(null);
  const [deleting, setDeleting] = useState(false);

  const { showTableLoading } = useVoucherListTableBusy(loading);

  const selection = useVoucherListSelection({
    rows: items,
    totalCount,
    page,
    pageSize,
    getRowId: r => r.id,
  });

  const activeRow = selection.activeRow;

  const refresh = useCallback(() => {
    selection.clearSelection();
    setReloadKey(k => k + 1);
  }, [selection]);

  const setPageSize = (size: number) => {
    setPageSizeState(size as ListPageSize);
    resetPage();
    selection.clearSelection();
  };

  React.useEffect(() => {
    if (!initialized) return;
    let cancelled = false;
    setLoading(true);
    const t = window.setTimeout(() => {
      bankStatementImportService.listImportVouchers({
        fromDate,
        toDate,
        processingLevel: processingLevel || undefined,
        companyCode: companyCode || undefined,
        search: search || undefined,
        page,
        pageSize,
      })
        .then(async res => {
          if (cancelled) return;
          const rows = res.items ?? [];
          // Group unique Auth user ids (CreatedBy + imported code nếu UUID) → 1 lần/user
          const authIds = rows.flatMap(r => {
            const ids: string[] = [];
            const created = (r.createdBy || '').trim();
            if (created) ids.push(created);
            const importCode = (r.importedByEmployeeCode || '').trim();
            if (looksLikeAuthUserId(importCode)) ids.push(importCode);
            return ids;
          });
          const authById = await resolveAuthUsersByIds(authIds);
          if (cancelled) return;
          setItems(
            rows.map(r => ({
              ...r,
              createdByDisplay: displayCreatedBy(r, authById),
              importedByDisplay: displayImportedBy(r, authById),
            })),
          );
          setTotalCount(res.totalCount ?? 0);
        })
        .catch(err => {
          if (!cancelled) {
            dispatchAppToast(dispatch, {
              message: getApiErrorMessage(err, labels.listLoadError),
              type: 'error',
            });
          }
        })
        .finally(() => {
          if (!cancelled) setLoading(false);
        });
    }, 0);
    return () => {
      cancelled = true;
      window.clearTimeout(t);
    };
  }, [initialized, fromDate, toDate, processingLevel, companyCode, search, page, pageSize, reloadKey, dispatch]);

  const navigateToRow = useCallback((row: ListRow) => {
    navigate(`${KT.IMPORT_SAO_KE}/${row.id}`);
  }, [navigate]);

  const handleRowOpenActionMenu = useCallback(
    ({ row, x, y }: { row: ListRow; x: number; y: number }) => {
      selection.selectActiveRow(row);
      setRowMenu({ x, y, row });
    },
    [selection],
  );

  const openDelete = useCallback((row: ListRow) => {
    if (!canDelete) {
      dispatchAppToast(dispatch, { message: 'Bạn không có quyền xóa chứng từ IMP', type: 'warning' });
      return;
    }
    if (!canDeleteImp(row)) {
      dispatchAppToast(dispatch, { message: labels.deleteBlockedConfirmed, type: 'warning' });
      return;
    }
    setDeleteTarget(row);
  }, [canDelete, dispatch]);

  const handleConfirmDelete = useCallback(async () => {
    if (!deleteTarget) return;
    setDeleting(true);
    try {
      await bankStatementImportService.deleteImportVoucher(deleteTarget.id);
      dispatchAppToast(dispatch, { message: labels.deleteSuccess, type: 'success' });
      setDeleteTarget(null);
      refresh();
    } catch (err) {
      dispatchAppToast(dispatch, {
        message: getApiErrorMessage(err, labels.deleteError),
        type: 'error',
      });
    } finally {
      setDeleting(false);
    }
  }, [deleteTarget, dispatch, refresh]);

  const handleRowMenuSelect = useCallback(
    (action: VoucherRowMenuAction) => {
      const row = rowMenu?.row;
      if (!row) return;
      if (action === 'view' || action === 'edit') {
        navigateToRow(row);
      } else if (action === 'delete') {
        openDelete(row);
      }
    },
    [rowMenu?.row, navigateToRow, openDelete],
  );

  const handleFilterSearch = useCallback(() => {
    setSearch(searchDraft.trim());
    setCompanyCode(companyCodeDraft.trim());
    resetPage();
    setReloadKey(k => k + 1);
  }, [searchDraft, companyCodeDraft, resetPage]);

  const continueLabel = (row: BankStatementImportVoucherListItem) => {
    const step = resolveImportResumeStep(row.processingLevel);
    return step === 4 ? labels.continueConfirm : labels.continueClassify;
  };

  const toolbarActions = useMemo(() => {
    const base = buildVoucherListToolbarActions({
      testIdPrefix,
      onRefresh: refresh,
      canView: Boolean(activeRow),
      onView: () => activeRow && navigateToRow(activeRow),
      canEdit: Boolean(activeRow && canUpdate && canDeleteImp(activeRow)),
      onEdit: () => activeRow && navigateToRow(activeRow),
      canCreate,
      onCreate: () => navigate(KT.IMPORT_SAO_KE_NEW),
    });
    return [
      ...base.filter(a => a.id !== 'create'),
      {
        id: 'delete',
        placement: 'right' as const,
        action: 'delete' as const,
        disabled: !canDelete || !canDeleteImp(activeRow),
        onClick: () => activeRow && openDelete(activeRow),
        testId: `${testIdPrefix}-toolbar-delete-btn`,
      },
      ...base.filter(a => a.id === 'create'),
    ];
  }, [activeRow, canCreate, canUpdate, canDelete, refresh, navigate, navigateToRow, openDelete]);

  const listFilters = useMemo(
    () => (
      <LinErpListFilterBar
        testIdPrefix={testIdPrefix}
        fromDate={fromDate}
        toDate={toDate}
        onDateChange={(from, to) => {
          applyDateRange(from, to, detectDateRangePreset(from, to) || 'custom');
          resetPage();
        }}
        dateLabel="Ngày sao kê"
        onSearch={handleFilterSearch}
        loading={showTableLoading}
        leading={(
          <>
            <div data-testid={`${testIdPrefix}-field-processingLevel`}>
              <Select
                label="Mức xử lý"
                value={processingLevel}
                onChange={e => { setProcessingLevel(e.target.value); resetPage(); }}
                options={[...IMPORT_SAO_KE_PROCESSING_OPTIONS]}
                data-testid={`${testIdPrefix}-filter-processingLevel`}
              />
            </div>
            <div data-testid={`${testIdPrefix}-field-companyCode`}>
              <SearchTextInput
                label="Đơn vị"
                value={companyCodeDraft}
                onChange={setCompanyCodeDraft}
                onSearch={handleFilterSearch}
                placeholder="Mã ĐVCS (vd. FM02)"
                testId={`${testIdPrefix}-filter-companyCode`}
              />
            </div>
            <div data-testid={`${testIdPrefix}-field-search`}>
              <SearchTextInput
                label="Tìm"
                value={searchDraft}
                onChange={setSearchDraft}
                onSearch={handleFilterSearch}
                placeholder="Số CT, người import, người tạo, TK…"
                testId={`${testIdPrefix}-filter-search`}
              />
            </div>
          </>
        )}
      />
    ),
    [
      fromDate,
      toDate,
      processingLevel,
      companyCodeDraft,
      searchDraft,
      applyDateRange,
      resetPage,
      setProcessingLevel,
      handleFilterSearch,
      showTableLoading,
    ],
  );

  const rowMenuHintMessage = viewMobile
    ? VOUCHER_LIST_ROW_MENU_HINT_TOUCH
    : VOUCHER_LIST_ROW_MENU_HINT_DESKTOP;

  const listBody = !showTableLoading && items.length === 0 ? (
    <div className={erp.empty}>{labels.empty}</div>
  ) : !showTableLoading ? (
    <ErpDataListGrid
      testIdPrefix={testIdPrefix}
      rows={items}
      page={page}
      pageSize={pageSize}
      selection={selection}
      getRowId={r => r.id}
      onRowDoubleClick={navigateToRow}
      onRowOpenActionMenu={handleRowOpenActionMenu}
      rowMenuHintMessage={rowMenuHintMessage}
      rowMenuHintDismissStorageKey={voucherListRowMenuHintDismissStorageKey(testIdPrefix)}
      enableRowMenuLongPress={viewMobile}
      headerCells={(
        <>
          <th>Số CT</th>
          <th>Tiêu đề</th>
          <th>Ngày sao kê</th>
          <th>Người import</th>
          <th>Người tạo</th>
          <th>TK nghiệp vụ</th>
          <th>Kỳ</th>
          <th>Dòng</th>
          <th>Thu</th>
          <th>Chi</th>
          <th>Mức XL</th>
          <th>Đơn vị</th>
          <th>Tiếp tục</th>
        </>
      )}
      renderRow={(row, rowNo) => (
        <>
          <td data-testid={`${testIdPrefix}-row-${rowNo}-code`}>{row.code}</td>
          <td data-testid={`${testIdPrefix}-row-${rowNo}-title`}>
            {formatImportSaoKeTitle(row) || '—'}
          </td>
          <td data-testid={`${testIdPrefix}-row-${rowNo}-transaction-date`}>
            {formatDateLocal(row.transactionDate || row.importedAt)}
          </td>
          <td data-testid={`${testIdPrefix}-row-${rowNo}-imported-by`}>
            {row.importedByDisplay || row.importedByName || row.importedByEmployeeCode || '—'}
          </td>
          <td data-testid={`${testIdPrefix}-row-${rowNo}-created-by`}>
            {row.createdByDisplay || row.createdBy?.trim() || '—'}
          </td>
          <td>{row.accountCode}</td>
          <td>{row.monthCode}</td>
          <td>{row.statementLineCount}</td>
          <td className={erp.colAmount}>{formatMoney(row.totalCredit)}</td>
          <td className={erp.colAmount}>{formatMoney(row.totalDebit)}</td>
          <td>
            <span className={styles.levelBadge}>
              {formatImportSaoKeProcessingLevel(row.processingLevel)}
            </span>
          </td>
          <td>{row.companyCode || '—'}</td>
          <td>
            <button
              type="button"
              className={styles.continueLink}
              data-testid={`${testIdPrefix}-row-${rowNo}-continue`}
              onClick={e => {
                e.stopPropagation();
                navigateToRow(row);
              }}
            >
              {continueLabel(row)}
            </button>
          </td>
        </>
      )}
    />
  ) : null;

  return (
    <div
      className={erp.voucherListRoot}
      data-voucher-list-page
      data-testid={`${testIdPrefix}-list`}
    >
      <LinPageLayout
        kind="voucher"
        testIdPrefix={testIdPrefix}
        pageId={pageId}
        pageClassName={`${erp.catalogListPage} ${erp.voucherListPage}`}
        header={{
          title: labels.listPageTitle,
          titleIconClass: 'fas fa-file-import',
          pageId,
        }}
        toolbarProps={{
          testIdPrefix,
          profile: 'voucher',
          actions: toolbarActions,
        }}
        listTitle={labels.listTitle}
        listRowMenuHelp
        filters={listFilters}
        listLayoutVariant="erp-filter-bar"
        listHeaderClassName={LIN_ERP_LIST_FILTER_LAYOUT.header}
        listFiltersClassName={LIN_ERP_LIST_FILTER_LAYOUT.filtersHost}
        showTableLoading={showTableLoading}
        skeletonRows={Math.min(pageSize, 8)}
        footer={(
          <VoucherListPagination
            testIdPrefix={testIdPrefix}
            page={page}
            totalCount={totalCount}
            pageSize={pageSize}
            onPageChange={p => { setPage(p); selection.clearSelection(); }}
            onPageSizeChange={setPageSize}
          />
        )}
        modals={(
          <>
            <VoucherRowActionMenu
              open={Boolean(rowMenu)}
              x={rowMenu?.x ?? 0}
              y={rowMenu?.y ?? 0}
              onClose={() => setRowMenu(null)}
              onSelect={handleRowMenuSelect}
              testIdPrefix={testIdPrefix}
              showView
              showEdit={Boolean(rowMenu?.row && canUpdate && canDeleteImp(rowMenu.row))}
              showDelete={Boolean(rowMenu?.row && canDelete && canDeleteImp(rowMenu.row))}
              showViewLedger={false}
              showPrint={false}
            />
            <Modal
              isOpen={Boolean(deleteTarget)}
              onClose={() => !deleting && setDeleteTarget(null)}
              title={labels.deleteConfirmTitle}
            >
              <p>
                {labels.deleteConfirmBody}
                {deleteTarget?.code ? (
                  <>
                    {' '}
                    (
                    <strong>{deleteTarget.code}</strong>
                    )
                  </>
                ) : null}
              </p>
              <div style={{ display: 'flex', gap: 8, justifyContent: 'flex-end', marginTop: 16 }}>
                <Button
                  variant="secondary"
                  onClick={() => setDeleteTarget(null)}
                  disabled={deleting}
                  data-testid={`${testIdPrefix}-delete-cancel`}
                >
                  Hủy
                </Button>
                <Button
                  variant="danger"
                  onClick={() => { void handleConfirmDelete(); }}
                  loading={deleting}
                  data-testid={`${testIdPrefix}-delete-confirm`}
                >
                  {labels.delete}
                </Button>
              </div>
            </Modal>
          </>
        )}
      >
        {listBody}
      </LinPageLayout>
    </div>
  );
};

export default ImportSaoKeListPage;
