import { useVoucherListActions } from './useVoucherListActions';
import { hasPermissionCode } from '../utils/erpPermissionCode';
import { IMPORT_SAO_KE_LIST_INIT_FORM } from '../constants/importSaoKeInit';

const PREFIX = 'erp-finance:bank-statement-imports';

/**
 * IMP list/wizard gates — init-data formPermissions + granular confirm.
 * Auth CSV: `{prefix}:read|write|delete|approve` (approve = Confirm Step 4).
 */
export function useImportSaoKePermissions() {
  const {
    loading,
    formPermissions,
    canCreate,
    canUpdate,
    canApprove,
  } = useVoucherListActions(IMPORT_SAO_KE_LIST_INIT_FORM);

  const canRead =
    hasPermissionCode(`${PREFIX}:read`)
    || hasPermissionCode(`${PREFIX}:write`)
    || canCreate
    || canUpdate;

  const canDelete =
    hasPermissionCode(`${PREFIX}:delete`)
    || (formPermissions?.canDelete ?? false);

  /** Step 4 Confirm tạo CT con — map `approve` (parity voucher phê duyệt). */
  const canConfirm =
    hasPermissionCode(`${PREFIX}:approve`)
    || canApprove
    || hasPermissionCode(`${PREFIX}:write`);

  return {
    loading,
    formPermissions,
    canRead,
    canCreate,
    canUpdate,
    canDelete,
    canConfirm,
  };
}
